// Milestone wave (all URLs verified live + iframe-friendly): pushes the library past 450 modules.
// Sources: PhET (8), Simon Tatham puzzles (8), Learn.Genetics (6), MolView molecules (10), musictheory.net (6),
// Toy Theater (4), WGG geography (4), GeoGebra (3), + 3 language/CS extras.
const J = (v: unknown) => JSON.stringify(v);
const E = (source: string, sourceLabel: string, url: string, aspect: string, attributionName: string, attributionUrl: string, license: string, missions: string[]) =>
  J({ source, sourceLabel, url, aspect, attributionName, attributionUrl, license, missions });

const MOL = (cid: string, label: string, url: string, attributionName: string, missions: string[]) =>
  J({ source: "molview", sourceLabel: label, url, aspect: "1/1", attributionName, attributionUrl: "https://molview.org/", license: "Free for education (CC)", missions });

